<title>海牙体系概况</title>
<style>
    body {
        margin: 0;
        padding: 0;
        display: flex;
        justify-content: center;
        align-items: center;
        min-height: 100vh;
        background-color: #e0e0e0;
        font-family: 'Microsoft YaHei', 'SimHei', sans-serif;
    }

    .slide-container {
        width: 1024px;
        height: 768px;
        background: linear-gradient(135deg, #dcf0f4 0%, #f2f9fa 50%, #e6f2f5 100%);
        position: relative;
        overflow: hidden;
        box-sizing: border-box;
        padding: 40px 60px;
        box-shadow: 0 4px 8px rgba(0,0,0,0.1);
    }

    /* Watermark Styling */
    .watermark {
        position: absolute;
        font-size: 42px;
        color: rgba(160, 170, 180, 0.25);
        transform: rotate(-30deg);
        white-space: nowrap;
        pointer-events: none;
        font-weight: bold;
        letter-spacing: 2px;
        z-index: 0;
    }
    .wm1 { top: 15%; left: -15%; }
    .wm2 { top: 45%; left: 5%; }
    .wm3 { top: 75%; left: 25%; }
    .wm4 { top: 5%; left: 35%; }
    .wm5 { top: 35%; left: 55%; }
    .wm6 { top: 65%; left: 75%; }

    /* Content Wrapper to sit above watermark */
    .content-wrapper {
        position: relative;
        z-index: 1;
        height: 100%;
        display: flex;
        flex-direction: column;
    }

    /* Header */
    .header {
        display: flex;
        justify-content: space-between;
        align-items: flex-start;
        margin-bottom: 30px;
    }

    .main-title {
        color: #c00000;
        font-size: 46px;
        font-family: 'KaiTi', 'STKaiti', serif;
        margin: 0;
        padding-top: 10px;
    }

    .header-right {
        display: flex;
        align-items: center;
        background: linear-gradient(to right, transparent, #8bc3d1 20%, #8bc3d1 100%);
        padding: 5px 15px 5px 0;
        border-radius: 25px 0 0 25px;
    }

    .placeholder.logo {
        width: 60px;
        height: 50px;
        background-color: #fff;
        border: 1px solid #ccc;
        border-radius: 50%;
        display: flex;
        justify-content: center;
        align-items: center;
        font-size: 12px;
        color: #666;
        margin-right: 15px;
        box-shadow: 2px 2px 5px rgba(0,0,0,0.2);
    }

    .header-text {
        display: flex;
        flex-direction: column;
        align-items: flex-end;
    }

    .gongyi-title {
        color: #ffffff;
        font-size: 28px;
        font-weight: bold;
        text-shadow: 1px 1px 3px rgba(0,0,0,0.6);
        letter-spacing: 2px;
        margin-bottom: 2px;
    }

    .website-url {
        color: #ffffff;
        font-size: 14px;
        font-family: Arial, sans-serif;
    }

    /* Sub Header */
    .sub-header {
        color: #002060;
        font-size: 32px;
        font-weight: bold;
        margin-bottom: 40px;
        display: flex;
        align-items: center;
    }

    .square-bullet {
        color: #002060;
        margin-right: 10px;
        font-size: 24px;
    }

    /* Columns */
    .columns-container {
        display: flex;
        justify-content: space-between;
        padding: 0 20px;
        margin-bottom: auto; /* Pushes footer down */
    }

    .column {
        width: 45%;
    }

    .col-heading {
        color: #c00000;
        font-size: 34px;
        text-align: center;
        margin-bottom: 30px;
        font-family: 'KaiTi', 'STKaiti', serif;
    }

    ul {
        list-style-type: none;
        padding: 0;
        margin: 0;
    }

    li {
        color: #c00000;
        font-size: 26px;
        margin-bottom: 18px;
        position: relative;
        padding-left: 35px;
        line-height: 1.3;
        font-family: 'KaiTi', 'STKaiti', serif;
    }

    li::before {
        content: "●";
        color: #c00000;
        position: absolute;
        left: 0;
        top: 0;
        font-size: 22px;
    }

    /* Footer Note */
    .footer-note {
        color: #002060;
        font-size: 24px;
        line-height: 1.6;
        margin-bottom: 20px;
        display: flex;
        align-items: flex-start;
    }

    .footer-note .square-bullet {
        margin-top: 4px;
        font-size: 20px;
    }

    .highlight-red {
        color: #c00000;
        font-weight: bold;
    }

    /* Page Number */
    .page-number {
        position: absolute;
        bottom: 20px;
        right: 30px;
        color: #666;
        font-size: 18px;
        font-family: Arial, sans-serif;
    }
</style>
</head>
